// Prefiks data- jest OFICJALNA, ZALECANA czescia standardu HTML5,
// zaprojektowana SPECJALNIE do przechowywania wlasnych, niestandardowych
// danych bezposrednio na elementach HTML. W przeciwienstwie do
// wymyslania dowolnych, wlasnych atrybutow (np. mojAtrybut='x'), ktore
// bylyby niepoprawne wedlug specyfikacji HTML (walidatory HTML
// zglosilyby blad), atrybuty data-* sa jawnie dozwolone i wspierane
// przez wszystkie nowoczesne przegladarki, wraz z wygodnym dostepem
// przez wlasciwosc dataset w JavaScript.

const produkt = document.getElementById("product-2");
produkt.setAttribute("alt", "Zdjecie produktu");
console.log(produkt.hasAttribute("alt"));

