const produkt = document.getElementById("product-2");
produkt.removeAttribute("data-category");
console.log(produkt.dataset.category);

function pobierzCeneJakoLiczbe(elementId) {
  return Number(document.getElementById(elementId).dataset.price);
}

console.log(pobierzCeneJakoLiczbe("product-1"));

function dataAtrybutNaKlucz(nazwa) {
  return nazwa.replace(/^data-/, "").replace(/-([a-z])/g, (_, litera) => litera.toUpperCase());
}

console.log(dataAtrybutNaKlucz("data-in-stock"));

const input = document.getElementById("search-input");
