console.log(input.getAttribute("type"));

// Prefiks data- jest oficjalna, zalecana czescia standardu HTML5,
// zaprojektowana specjalnie do przechowywania wlasnych, niestandardowych
// danych na elementach HTML. Wymyslanie dowolnych, wlasnych atrybutow
// (np. mojAtrybut="x") jest NIEPOPRAWNE wedlug specyfikacji HTML -
// walidatory HTML zglosza blad. Atrybuty data-* sa jawnie dozwolone
// i wspierane przez wszystkie nowoczesne przegladarki, z wygodnym
// dostepem przez wlasciwosc dataset.

const produkt = document.getElementById("product-3");
produkt.dataset.rabat = "10";
console.log(Number(produkt.dataset.rabat) === 10);

function czyDostepny(elementId) {
  return document.getElementById(elementId).dataset.stan === "dostepny";
}

document.getElementById("product-1").dataset.stan = "dostepny";
console.log(czyDostepny("product-1"));

const produkt = document.getElementById("product-1");
for (const klucz of Object.keys(produkt.dataset)) {
  console.log(klucz);
}

function ustawAtrybutBezpiecznie(elementId, nazwa, wartosc) {
  document.getElementById(elementId).setAttribute(nazwa, String(wartosc));
}

ustawAtrybutBezpiecznie("product-1", "data-ocena", 5);
console.log(document.getElementById("product-1").getAttribute("data-ocena"));

const produkt = document.getElementById("product-3");
console.log(produkt.getAttribute("nieistniejacy-atrybut"));
console.log(produkt.dataset.nieistniejacyKlucz);

// Standardowe atrybuty (id, title, href) sa jak oficjalne metki na
// produkcie - maja ustalone, znane znaczenie (cena, rozmiar), rozumiane
// przez kazda przegladarke.
// Atrybuty data-* sa jak specjalna, pusta "kieszen" na produkcie, gdzie
// mozesz wpisac wlasne, prywatne notatki (np. wewnetrzny numer
// katalogowy) - nie maja standardowego znaczenia dla przegladarki, ale
// sa latwo dostepne dla wlasnego kodu JavaScript przez dataset.

const produkt = document.getElementById("product-1");
produkt.dataset.ostatniaAktualizacja = Date.now().toString();
console.log(typeof produkt.dataset.ostatniaAktualizacja);

function porownajCeny(idA, idB) {
  const cenaA = Number(document.getElementById(idA).dataset.price);
  const cenaB = Number(document.getElementById(idB).dataset.price);
  return cenaA < cenaB;
}

console.log(porownajCeny("product-1", "product-2"));

function czyWTrakcieWyprzedazy(elementId) {
  return document.getElementById(elementId).dataset.wyprzedaz === "true";
}

document.getElementById("product-3").dataset.wyprzedaz = "true";
console.log(czyWTrakcieWyprzedazy("product-3"));

const produkt = document.getElementById("product-1");
produkt.dataset.wyprzedaz = "true";
console.log(produkt.dataset.wyprzedaz === true);

function ustawWieleAtrybutow(elementId, atrybuty) {
  const element = document.getElementById(elementId);
  for (const [nazwa, wartosc] of Object.entries(atrybuty)) {
    element.setAttribute(nazwa, wartosc);
  }
}

ustawWieleAtrybutow("product-1", { title: "Nowosc", "data-promo": "tak" });
console.log(document.getElementById("product-1").getAttribute("data-promo"));

